/**
 * Strong TypeScript definitions for the official Razorpay Checkout SDK (checkout.js).
 * Based on official Razorpay Web Checkout Integration Specifications.
 */

export interface RazorpayPaymentSuccessResponse {
  /** Gateway generated unique payment identifier (e.g. 'pay_29QQoUBcxQtv4e') */
  razorpay_payment_id: string;

  /** Gateway generated order identifier matching the checkout order (e.g. 'order_9A33XWu170gUtm') */
  razorpay_order_id: string;

  /** Cryptographic HMAC-SHA256 signature generated by Razorpay */
  razorpay_signature: string;
}

export interface RazorpayErrorMetadata {
  order_id?: string;
  payment_id?: string;
}

export interface RazorpayErrorDetail {
  code: string;
  description: string;
  source: string;
  step: string;
  reason: string;
  metadata?: RazorpayErrorMetadata;
}

export interface RazorpayErrorResponse {
  error: RazorpayErrorDetail;
}

export interface RazorpayPrefill {
  name?: string;
  email?: string;
  contact?: string;
  method?: 'card' | 'netbanking' | 'wallet' | 'upi';
}

export interface RazorpayTheme {
  color?: string;
  hide_topbar?: boolean;
  backdrop_color?: string;
}

export interface RazorpayModalOptions {
  backdropclose?: boolean;
  escape?: boolean;
  handleback?: boolean;
  confirm_close?: boolean;
  ondismiss?: () => void;
  animation?: boolean;
}

export interface RazorpayRetryOptions {
  enabled?: boolean;
  max_count?: number;
}

export interface RazorpayOptions {
  /** Razorpay Public Key ID (e.g. 'rzp_test_...' or 'rzp_live_...'). Never put secrets here. */
  key: string;

  /** Payment amount in currency sub-units (e.g. paise for INR: ₹100.00 = 10000) */
  amount?: number;

  /** 3-letter ISO currency code (default: 'INR') */
  currency?: string;

  /** Platform/Merchant branding name */
  name?: string;

  /** Brief description shown in the checkout modal (e.g. 'Booking Ref: BK-1001') */
  description?: string;

  /** Optional URL of merchant logo displayed in the checkout modal */
  image?: string;

  /** Order ID generated server-side via Razorpay Orders API */
  order_id: string;

  /** Handler function invoked upon successful payment capture with cryptographic signature */
  handler?: (response: RazorpayPaymentSuccessResponse) => void;

  /** Customer contact prefill options */
  prefill?: RazorpayPrefill;

  /** Custom key-value pairs associated with the checkout session */
  notes?: Record<string, string>;

  /** Modal visual styling */
  theme?: RazorpayTheme;

  /** Modal behavior and dismissal callbacks */
  modal?: RazorpayModalOptions;

  /** Checkout session timeout in seconds */
  timeout?: number;

  /** Automatic retry options */
  retry?: RazorpayRetryOptions;

  /** Android SMS auto-read hash */
  send_sms_hash?: boolean;

  /** Extensible custom properties */
  [key: string]: unknown;
}

export interface RazorpayInstance {
  /** Opens the Razorpay payment modal */
  open(): void;

  /** Closes the active Razorpay payment modal */
  close(): void;

  /** Registers event listener for payment failures */
  on(event: 'payment.failed', handler: (response: RazorpayErrorResponse) => void): void;

  /** Registers generic event listener */
  on(event: string, handler: (data: unknown) => void): void;
}

export interface RazorpayConstructor {
  new (options: RazorpayOptions): RazorpayInstance;
}

declare global {
  interface Window {
    Razorpay?: RazorpayConstructor;
  }
}

